  <meta name="color-scheme" content="light dark">
  <title>Northwind consolidation review</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <a class="skip" href="#view">Skip to the main panel</a>
  <header class="top">
    <a href="#/" class="brand">Northwind consolidation</a>
    <div id="runbar" class="runbar" aria-live="polite"></div>
  </header>
  <div class="layout">
    <nav id="stepper" class="stepper" aria-label="Steps"></nav>
    <main id="view" tabindex="-1"></main>
  </div>
  <footer class="foot">This page runs only on this machine (127.0.0.1). Your files stay here and no live model is called from it.</footer>
  <script src="app.js"></script>
  <script src="format.js"></script>
  <script src="issues.js"></script>
  <script src="ai.js"></script>
  <script src="viewer.js"></script>
  <script src="workbench.js"></script>
  <script src="steps.js"></script>
  <script>route();</script>
</body>
</html>
// Review UI: hash router, API helper and the runs list. Everything from the server is put on the page with
// text nodes (never as HTML), so uploaded text is shown as data and cannot run as script.
const STEPS = [["upload", "1 Upload"], ["scan", "2 Scan"], ["review", "3 Review inputs"], ["build", "4 Generate"],
