function aiBlock(ai) {
  const dropped = ai.dropped.length ? h("ul", {}, ai.dropped.map((d) => h("li", {}, h("code", {}, d.claim), ": ", d.why))) : null;
  return h("section", { class: "wb-ai" }, h("h3", {}, "What the AI said about this row"),
