"""control_figures_pb.json (a number, or null) and control_figures_status.json (why null, what is provisional)."""
from decimal import Decimal
from pathlib import Path
from typing import TYPE_CHECKING

from app.core.figures import KEYS
from app.domain.figures import Determined, Provisional, Unknown
from app.utils.hashing import dumps
from app.utils.money import round_tree
from app.writers.statements import write_text

if TYPE_CHECKING:
    from app.services.run_service import Consolidation

# the brief's appendix: control_figures_<your initials>.json
INITIALS = "pb"


def figure_values(run: "Consolidation") -> dict[str, object]:
    out: dict[str, object] = {}
    for key in KEYS:
        figure = run.figures[key]
        out[key] = None if isinstance(figure, Unknown) else figure.value
    return out


def figure_status(run: "Consolidation") -> dict[str, object]:
    status: dict[str, object] = {}
    for key in KEYS:
        figure = run.figures[key]
        if isinstance(figure, Unknown):
            status[key] = {"status": "unknown", "reason": figure.reason}
        elif isinstance(figure, Provisional):
            status[key] = {"status": "provisional", "open_items": list(figure.open_items)}
        elif isinstance(figure, Determined):
            status[key] = {"status": "determined"}
    causes: dict[str, Decimal] = dict(run.ic.causes) if run.ic else {}
    return {"figures": status, "intercompany_causes": causes, "checks_passed": run.checks_passed,
            "blocked": run.blocked}


def write_control_figures(run: "Consolidation", out: Path) -> None:
    write_text(out / f"control_figures_{INITIALS}.json", dumps(round_tree(figure_values(run))))
    write_text(out / "control_figures_status.json", dumps(round_tree(figure_status(run))))

"""The run registry: one folder per run under .northwind/runs/<id>/ holding its own data, config, outputs and logs.
Config is copied per run so an approval written by one run never changes the repository's overrides.toml."""
import json
import re
import secrets
import shutil
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from app.orchestrator.state import RunState, initial_state
from app.utils.paths import CONFIG_DIR, DEFAULT_DATA_DIR

RUN_ID = re.compile(r"^r\d{8}-\d{6}-[0-9a-f]{4}$")
CONFIG_COPIED = ("policy.toml", "assumptions.toml", "overrides.toml", "bundle_manifest.sha256")


class UnknownRun(Exception):
    pass


class Registry:
    def __init__(self, root: Path) -> None:
        self.root = root

    def folder(self, run_id: str) -> Path:
        """The id is checked against a strict pattern before it touches the file system."""
        if not RUN_ID.match(run_id) or not (self.root / run_id / "run.json").is_file():
            raise UnknownRun(run_id)
        return self.root / run_id

    def data_dir(self, run_id: str) -> Path:
        return self.folder(run_id) / "data"

    def config_dir(self, run_id: str) -> Path:
        return self.folder(run_id) / "config"

    def out_dir(self, run_id: str) -> Path:
        return self.folder(run_id) / "output"

    def meta(self, run_id: str) -> dict[str, Any]:
        return dict(json.loads((self.folder(run_id) / "run.json").read_text(encoding="utf-8")))

    def update(self, run_id: str, **fields: Any) -> dict[str, Any]:
        meta = self.meta(run_id) | fields
        (self.folder(run_id) / "run.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
        return meta

    def create(self, name: str = "", use_sample: bool = False, parent: str | None = None,
               copy_data_from: Path | None = None, copy_config_from: Path = CONFIG_DIR) -> dict[str, Any]:
        stamp = datetime.now(UTC).strftime("%Y%m%d-%H%M%S")
        run_id = f"r{stamp}-{secrets.token_hex(2)}"
        folder = self.root / run_id
        (folder / "data").mkdir(parents=True)
        (folder / "config").mkdir()
        for name_ in CONFIG_COPIED:
            shutil.copy2(copy_config_from / name_, folder / "config" / name_)
        source = copy_data_from or (DEFAULT_DATA_DIR if use_sample else None)
        if source is not None:
            shutil.copytree(source, folder / "data", dirs_exist_ok=True)
        meta: dict[str, Any] = {"id": run_id, "name": name.strip() or run_id, "created": datetime.now(UTC).isoformat(),
                "parent": parent, "status": "new", "open_items": [], "thread": None, "outputs": None}
        (folder / "run.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
        return meta

    def list(self, archived: bool = False) -> list[dict[str, Any]]:
        """Runs in use, or with archived=True the archived ones. Archiving hides a run; nothing is deleted."""
        found = [self.meta(p.name) for p in self.root.glob("r*") if RUN_ID.match(p.name) and (p / "run.json").is_file()]
        shown = [m for m in found if bool(m.get("archived")) == archived]
        return sorted(shown, key=lambda m: str(m["created"]), reverse=True)

    def state(self, run_id: str) -> RunState:
        folder = self.folder(run_id)
        return initial_state(folder / "data", folder / "output", folder / "config", folder / "run.db",
                             folder / "logs")

"""A second implementation of the same method, recomputing the control figures from the raw files.

It shares the policy and the assumptions (A1, A3, A6, A9, and the 2310 remap switch passed in by the run), so it is not
an independent check of the accounting. It imports nothing from app.core or app.parsers (only the figure names and
the invariants): it reads the files itself, works entity by entity in local
currency, and translates once at the end. A disagreement with the pipeline is reported, never adjusted away."""
import csv
import json
import re
from decimal import Decimal as D
from pathlib import Path
from typing import Any

from app.domain.figures import Determined, Figure, Provisional, Unknown
from app.verification.invariants import Check

NUMERIC = ("group_revenue", "group_profit", "profit_owners", "profit_nci", "nci_closing", "goodwill_closing",
           "translation_reserve_movement", "total_assets", "total_equity", "intercompany_difference")
Books = dict[str, D]


def _rows(path: Path) -> list[dict[str, str]]:
    with open(path, newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


class Rates:
    def __init__(self, path: Path) -> None:
        self.value: dict[tuple[str, str, str], D] = {}
        self.window: dict[str, str] = {}
        for r in _rows(path):
            units = r["convention"].split(" per 1 ")[0]
            rate = D(r["rate"]) if units == r["quote_currency"] else 1 / D(r["rate"])
            self.value[(r["base_currency"], r["quote_currency"], r["rate_type"])] = rate
            self.window[r["as_of"]] = r["rate_type"]

    def per_gbp(self, ccy: str, kind: str) -> D:
        usd = self.value[("GBP", "USD", kind)]
        return usd if ccy == "USD" else usd * self.value[("USD", ccy, kind)]


def _add(books: Books, code: str, amount: D) -> None:
    books[code] = books.get(code, D(0)) + amount


def _plus(books: Books, coa: dict[str, dict[str, str]], **match: str) -> D:
    return sum((v for k, v in books.items() if all(coa[k][f] == w for f, w in match.items())), D(0))


def _journals(data: Path, known: dict[str, set[str]], opening: dict[tuple[str, str], D],
              side: dict[tuple[str, str], str]) -> tuple[dict[str, str], list[dict[str, Any]]]:
    """posted, rejected or held for each journal, by rules written afresh here."""
    raw: dict[str, Any] = json.loads(
        (data / "adjustments.json").read_text(encoding="utf-8"), parse_float=str, parse_int=str)
    seen: set[tuple[object, ...]] = set()
    status: dict[str, str] = {}
    balance = dict(opening)
    for e in raw["entries"]:
        lines = [(x["account"], D(x["debit"]), D(x["credit"])) for x in e["lines"]]
        key = (e["entity"], e["date"], tuple(sorted(lines)))
        repeat, unknown, flips = key in seen, any(a not in known[e["entity"]] for a, _, _ in lines), False
        seen.add(key)
        for account, dr, cr in ([] if unknown else lines):
            before = balance.get((e["entity"], account), D(0))
            balance[(e["entity"], account)] = before + dr - cr
            now, normal = before + dr - cr, side.get((e["entity"], account))
            flips = flips or (normal == "Credit" and before <= 0 < now) or (normal == "Debit" and before >= 0 > now)
        bad = sum(x[1] for x in lines) != sum(x[2] for x in lines) or not e["date"].startswith("2024") or repeat
        status[e["id"]] = "rejected" if bad else "held" if unknown or flips else "posted"
    return status, raw["entries"]


def recompute(data: Path, remap_deferred_income: bool = True) -> dict[str, object]:
    rates = Rates(data / "fx_rates.csv")
    coa = {r["account_code"]: r for r in _rows(data / "group_coa.csv")}
    maps = {e: {r["local_code"]: r["group_code"] for r in _rows(data / f"map_{e}.csv")} for e in ("uk", "in")}
    if remap_deferred_income:
        maps["uk"]["2310"] = "2300"
    ents = {r["entity_id"]: r for r in _rows(data / "entities.csv")}
    note = (data / "acquisition_note.md").read_text(encoding="utf-8")

"""Run registry, upload, review and build endpoints. Each calls one existing service."""
from typing import Annotated, Any

from fastapi import APIRouter, Depends, HTTPException, Request

from app.api_models import Decisions, NewRun
from app.services import pipeline_service as pipeline
from app.services.registry_service import Registry
from app.services.upload_service import EXPECTED_FILES, MAX_BYTES, file_status, validate_bytes

router = APIRouter(prefix="/api")


def registry(request: Request) -> Registry:
    reg: Registry = request.app.state.registry
    return reg


Reg = Annotated[Registry, Depends(registry)]


@router.get("/runs")
def list_runs(reg: Reg, archived: bool = False) -> list[dict[str, Any]]:
    return reg.list(archived)


@router.post("/runs/{run_id}/archive")
def archive(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.update(run_id, archived=True)


@router.post("/runs/{run_id}/restore")
def restore(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.update(run_id, archived=False)


@router.post("/runs")
def create_run(body: NewRun, reg: Reg) -> dict[str, Any]:
    return reg.create(body.name, body.use_sample)


@router.get("/runs/{run_id}")
def open_run(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.meta(run_id) | {"files": file_status(reg.data_dir(run_id))}


@router.put("/runs/{run_id}/files/{name}")
async def upload(run_id: str, name: str, request: Request, reg: Reg) -> dict[str, Any]:
    """The body is the raw file. It is checked against its contract in a scratch copy, then stored only if it passes."""
    if name not in EXPECTED_FILES:
        raise HTTPException(422, f"{name} is not one of the 15 expected files")
    folder = reg.data_dir(run_id)
    body = await request.body()
    if len(body) > MAX_BYTES:
        raise HTTPException(413, f"{name} is larger than {MAX_BYTES} bytes")
    error = validate_bytes(name, body)
    if error is None:
        (folder / name).write_bytes(body)
    return {"name": name, "stored": error is None, "error": error}


@router.post("/runs/{run_id}/analyse")
def analyse(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.analyse(reg, run_id)


@router.get("/runs/{run_id}/review")
def review(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.review_view(reg, run_id)


@router.post("/runs/{run_id}/decisions")
def decide(run_id: str, body: Decisions, reg: Reg) -> dict[str, Any]:
    return pipeline.decide(reg, run_id, body.approver, body.decisions)


@router.post("/runs/{run_id}/build")
def build(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.build(reg, run_id)

"""FastAPI server: creates the app, binds the routes, serves the UI. It listens on 127.0.0.1 only and writes under
.northwind/ (run folders). The model is never called from here: advice is replayed from the ledger."""
import re
from pathlib import Path

import uvicorn
from fastapi import FastAPI, Request
from fastapi.middleware.trustedhost import TrustedHostMiddleware
from fastapi.responses import JSONResponse, RedirectResponse
from fastapi.staticfiles import StaticFiles
from starlette.exceptions import HTTPException as StarletteHTTPException

from app import routes, routes_inputs, routes_results, routes_signoff
from app.parsers.contracts import ContractError
from app.services.pipeline_service import NotReady
from app.services.registry_service import Registry, UnknownRun
from app.utils.paths import ROOT, RUNTIME_DIR

HOST, PORT = "127.0.0.1", 8000
ALLOWED_HOSTS = ["127.0.0.1", "localhost"]  # a page on another name (DNS rebinding) is refused
PATH = re.compile(r"(?:[A-Za-z]:[\\/]|/)(?:[^\\/\s'\"<>|:]+[\\/])+([^\\/\s'\"<>|:]*)")


def scrub(text: str) -> str:
    """Keep the file name, drop the folders: an error must not tell a caller where the server keeps its files."""
    return PATH.sub(lambda m: m[1] or "", text)


def create_app(runs_root: Path = RUNTIME_DIR / "runs", frontend: Path = ROOT / "frontend") -> FastAPI:
    runs_root.mkdir(parents=True, exist_ok=True)
    app = FastAPI(title="Northwind consolidation review")
    app.state.registry = Registry(runs_root)
    app.add_middleware(TrustedHostMiddleware, allowed_hosts=ALLOWED_HOSTS)

    @app.exception_handler(UnknownRun)
    def unknown_run(_: Request, error: UnknownRun) -> JSONResponse:
        return JSONResponse({"detail": scrub(f"no such run: {error}")}, status_code=404)

    @app.exception_handler(NotReady)
    def not_ready(_: Request, error: NotReady) -> JSONResponse:
        return JSONResponse({"detail": scrub(str(error))}, status_code=409)

    @app.exception_handler(ContractError)
    def bad_input(_: Request, error: ContractError) -> JSONResponse:
        return JSONResponse({"detail": scrub(f"input rejected: {error}")}, status_code=422)

    @app.exception_handler(ValueError)
    def bad_value(_: Request, error: ValueError) -> JSONResponse:
        return JSONResponse({"detail": scrub(str(error))}, status_code=422)

    @app.exception_handler(StarletteHTTPException)
    def http_error(_: Request, error: StarletteHTTPException) -> JSONResponse:
        detail = scrub(error.detail) if isinstance(error.detail, str) else error.detail
        return JSONResponse({"detail": detail}, status_code=error.status_code)

    @app.exception_handler(Exception)
    def unexpected(_: Request, error: Exception) -> JSONResponse:
        return JSONResponse({"detail": scrub(f"{type(error).__name__}: {error}")}, status_code=500)

    app.include_router(routes.router)
    app.include_router(routes_results.router)
    app.include_router(routes_inputs.router)
    app.include_router(routes_signoff.router)
    app.mount("/ui", StaticFiles(directory=frontend, html=True), name="ui")

    @app.get("/", include_in_schema=False)
    def home() -> RedirectResponse:
        return RedirectResponse("/ui/")

    return app


def serve() -> int:
    print(f"Northwind review UI at http://{HOST}:{PORT}/")
    uvicorn.run(create_app(), host=HOST, port=PORT, log_level="warning")
    return 0

"""Read a finished run's output files for the viewer: a list with metadata, one file as tables, the issues on it.
Money stays as the exact text in the file (JSON numbers are read as strings), so the page never sees a float."""
import csv
import io
import json
from pathlib import Path
from typing import Any

from app.services.results_service import available_outputs
from app.utils.hashing import sha256_file

MAX_BYTES = 2_000_000
MAX_ROWS = 500
STATEMENTS = {"balance_sheet.json", "profit_and_loss.json", "changes_in_equity.json"}


class TooLarge(ValueError):
    """The file is over the size cap for the in-page view; it can still be downloaded."""


def _path(out_dir: Path, name: str) -> Path:
    if name not in {o["name"] for o in available_outputs(out_dir)}:
        raise ValueError(f"not an output of this run: {name}")
    return out_dir / name


def _flat(value: Any, prefix: str = "") -> list[list[str]]:
    if isinstance(value, dict):
        return [row for k, v in value.items() for row in _flat(v, f"{prefix}{k}.")]
    if isinstance(value, list) and all(not isinstance(v, (dict, list)) for v in value):
        return [[prefix.rstrip("."), "\n".join(str(v) for v in value)]]
    return [[prefix.rstrip("."), "" if value is None else str(value)]]


def _sections(data: Any) -> list[dict[str, Any]]:
    """A JSON file as tables: a list of records is a table, anything else is key and value rows."""
    if isinstance(data, list) or not isinstance(data, dict):
        data = {"records": data}
    sections, plain = [], []
    for key, value in data.items():
        if isinstance(value, list) and value and all(isinstance(v, dict) for v in value):
            columns = list(dict.fromkeys(k for v in value for k in v))
            rows = [["" if v.get(c) is None else str(v.get(c)) for c in columns] for v in value]
            sections.append({"title": key, "columns": columns, "rows": rows})
        else:
            plain += _flat(value, f"{key}.")
    if plain:
        sections.insert(0, {"title": "Details", "columns": ["Field", "Value"], "rows": plain})
    return sections


def _parse(path: Path) -> list[dict[str, Any]]:
    if path.stat().st_size > MAX_BYTES:
        raise TooLarge(f"{path.name} is over {MAX_BYTES:,} bytes: download it instead")
    text = path.read_text(encoding="utf-8")
    if path.suffix == ".csv":
        table = list(csv.reader(io.StringIO(text)))
        return [{"title": path.name, "columns": table[0], "rows": table[1:]}] if table else []
    return _sections(json.loads(text, parse_float=str, parse_int=str))


def file_list(out_dir: Path) -> list[dict[str, Any]]:
    rows = []
    for item in available_outputs(out_dir):
        path = out_dir / item["name"]
        try:
            count = sum(len(s["rows"]) for s in _parse(path))
        except TooLarge:
            count = None
        rows.append({"name": item["name"], "bytes": item["bytes"], "sha256": sha256_file(path), "rows": count})
    return rows


def file_view(out_dir: Path, name: str) -> dict[str, Any]:
    sections = _parse(_path(out_dir, name))
    total = sum(len(s["rows"]) for s in sections)
    left = MAX_ROWS
    for s in sections:
        s["rows"], left = s["rows"][:left], max(left - len(s["rows"]), 0)
    return {"name": name, "sections": sections, "total_rows": total, "truncated": total > MAX_ROWS,
            "sha256": sha256_file(out_dir / name), "bytes": (out_dir / name).stat().st_size}


def _read_csv(path: Path) -> tuple[list[str], list[list[str]]]:
    header, *rows = csv.reader(path.read_text(encoding="utf-8").splitlines())
    return header, rows


def _traced(out_dir: Path) -> dict[str, set[str]]:
    """For each output file, the input file:line references its rows come from (the source_rows columns). A statement
    is sourced from the consolidated accounts it lists."""
    refs: dict[str, set[str]] = {}
    by_account: dict[str, set[str]] = {}
    for name in ("consolidated_tb.csv", "eliminations.csv"):
        header, rows = _read_csv(out_dir / name)
        at = header.index("source_rows")
        refs[name] = {r.strip() for row in rows for r in row[at].split(";")}
        if name == "consolidated_tb.csv":
            by_account = {row[0]: {r.strip() for r in row[at].split(";")} for row in rows}
    for name in STATEMENTS & {o["name"] for o in available_outputs(out_dir)}:
        listed = {row[s["columns"].index("account")] for s in _parse(out_dir / name) if "account" in s["columns"]
                  for row in s["rows"]}
        refs[name] = set().union(*(by_account.get(a, set()) for a in listed))
    return refs


def issues_by_file(out_dir: Path, cards: list[dict[str, Any]], name: str) -> dict[str, list[dict[str, Any]]]:
    """Cards whose input file:line feeds this output (by its source rows), or that name a figure in this file. Cards
    that cannot be traced to this file are returned as run-wide: never guessed."""
    _path(out_dir, name)
    refs = _traced(out_dir).get(name, set())
    figures = set(json.loads((out_dir / "control_figures_pb.json").read_text(encoding="utf-8")))
    hit: list[dict[str, Any]] = []
    wide: list[dict[str, Any]] = []
    for card in cards:
        where = f"{card['evidence']['file']}:{card['evidence']['line']}"
        affects = (name == "issues.json" or where in refs
                   or (name.startswith("control_figures") and card["figure"] in figures))
        (hit if affects else wide).append(card)
    return {"affecting": hit, "run_wide": wide}

"""The steps behind the UI, each a thin call into an existing service: analyse and resume go through the same graph
the command line uses, review advice is replayed from the ledger only, and the gates are the engine's own checks."""
import json
from pathlib import Path
from typing import Any

from app.config import load_overrides
from app.llm.factory import load_llm_config
from app.llm.ledger import Ledger
from app.orchestrator.graph import resume_graph, run_graph, thread_for
from app.orchestrator.state import RunState
from app.services import ai_service
from app.services.cards_service import build_cards, held_cards, waiting_cards
from app.services.overrides_service import override_states, review_queue
from app.services.registry_service import Registry
from app.services.review_service import review_all
from app.services.run_service import Consolidation, build_context, input_hash, stage
from app.services.upload_service import file_status


class NotReady(Exception):
    """The step cannot run yet. The message says what is missing."""


def _checkpoints(registry: Registry, run_id: str) -> Path:
    return registry.folder(run_id) / "checkpoints.db"


HELD = "journal:"


def _held_pending(registry: Registry, run_id: str, meta: dict[str, Any]) -> list[str]:
    """Journals the rules held ('needs a human') that nobody has decided yet, as 'journal:JE-016'."""
    run = stage(build_context(registry.data_dir(run_id), registry.config_dir(run_id)))
    decided = meta.get("held_decisions", {})
    return [f"{HELD}{d.journal_id}" for d in run.dispositions if d.status == "HOLD" and d.journal_id not in decided]


def _with_held(registry: Registry, run_id: str, meta: dict[str, Any]) -> dict[str, Any]:
    """A finished run still waits while a held journal is undecided: its status goes back to awaiting_review."""
    if meta["status"] not in {"done", "awaiting_review"}:
        return meta
    waiting = [k for k in meta["open_items"] if not k.startswith(HELD)] + _held_pending(registry, run_id, meta)
    if not waiting and meta["status"] == "awaiting_review":
        return registry.update(run_id, status="done", open_items=[])
    return registry.update(run_id, status="awaiting_review" if waiting else "done", open_items=waiting)


def _store(registry: Registry, run_id: str, state: RunState) -> dict[str, Any]:
    meta = registry.update(run_id, status=state["status"], open_items=state.get("open_items", []),
                           blocked=state.get("blocked"), checks_passed=state.get("checks_passed"))
    return _with_held(registry, run_id, meta)


def analyse(registry: Registry, run_id: str) -> dict[str, Any]:
    bad = [r["name"] for r in file_status(registry.data_dir(run_id)) if not r["present"] or r["error"]]
    if bad:
        raise NotReady("fix or upload these files first: " + ", ".join(str(n) for n in bad))
    thread = thread_for(registry.data_dir(run_id), registry.config_dir(run_id))
    registry.update(run_id, thread=thread)
    return _store(registry, run_id, run_graph(registry.state(run_id), _checkpoints(registry, run_id)))


def decide(registry: Registry, run_id: str, approver: str, decisions: dict[str, str]) -> dict[str, Any]:
    meta = registry.meta(run_id)
    if meta["status"] != "awaiting_review":
        raise NotReady("this run is not waiting for a decision")
    unknown = sorted(set(decisions) - set(meta["open_items"]))
    if unknown:
        raise NotReady("not open for decision: " + ", ".join(unknown))
    held = {k[len(HELD):]: {"choice": v, "approver": approver} for k, v in decisions.items() if k.startswith(HELD)}
    meta = registry.update(run_id, held_decisions=meta.get("held_decisions", {}) | held)
    chosen = {k: v for k, v in decisions.items() if not k.startswith(HELD)}
    if not chosen:
        return _with_held(registry, run_id, meta)
    answer = {"approver": approver, "decisions": chosen}
    return _store(registry, run_id, resume_graph(meta["thread"], answer, _checkpoints(registry, run_id)))


def _advice(registry: Registry, run_id: str) -> list[dict[str, Any]]:
    """Recorded model advice. 'replay' never calls a model: a unit with no recorded answer reads 'not recorded'."""
    ctx = build_context(registry.data_dir(run_id), registry.config_dir(run_id))
    cfg = load_llm_config()
    rows = []
    for r in review_all(ctx, cfg, Ledger(cfg.ledger_path), "replay"):
        if r.grounded.verified or r.grounded.unverified or r.grounded.dropped or r.missed:
            rows.append({"kind": r.unit.kind, "unit": r.unit.unit_id, "source": r.source,
                         "recorded": r.source == "model", "verified": list(r.grounded.verified),
                         "unverified": list(r.grounded.unverified), "missed": list(r.missed),
                         "dropped": [{"claim": c, "why": w} for c, w in r.grounded.dropped]})
    return rows


def journal_memos(run: Consolidation) -> dict[str, dict[str, Any]]:
    """Text addressed to tools (D12), tied to the journal starting last at or before its line."""
    starts = sorted((j.ref.line, j.id) for j in run.ctx.inputs.journals)
    found = {}
    for f in run.findings:
        if f.code == "D12" and f.quoted_text is not None and f.line is not None:
            owner = [jid for line, jid in starts if line <= f.line]
            if owner:
                found[owner[-1]] = {"line": f.line, "text": f.quoted_text.text}
    return found


def review_view(registry: Registry, run_id: str) -> dict[str, Any]:
    ctx = build_context(registry.data_dir(run_id), registry.config_dir(run_id))
    run = stage(ctx)
    states = override_states(load_overrides(registry.config_dir(run_id) / "overrides.toml"), ctx.inputs)
    keep = ("key", "code", "severity", "claim", "file", "line", "action", "subject")
    findings = [{k: v for k, v in f.model_dump(mode="json").items() if k in keep} for f in run.findings]
    dispositions = [d.model_dump(mode="json") for d in run.dispositions]
    open_items = registry.meta(run_id)["open_items"]
    ai = ai_service.review_units(registry, run_id)
    units = ai["units"]
    return {
        "ai": ai, "findings": findings,
        "cards": build_cards(findings, units, dispositions, open_items, journal_memos(run)),
        "dispositions": dispositions,
        "waiting": waiting_cards(states, open_items) + held_cards(dispositions, open_items),
        "queue": review_queue(run.findings, states),
        "open_items": open_items,
        "advice": _advice(registry, run_id),
    }


def generated_now(registry: Registry, run_id: str) -> bool:
    """A Draft was generated for exactly the inputs and config the run holds now (see generate_service)."""
    meta = registry.meta(run_id)
    return meta.get("generated_for") == input_hash(registry.data_dir(run_id), registry.config_dir(run_id))


def require_done(registry: Registry, run_id: str) -> None:
    """Results need output. A run with an item undecided has output only if a Draft was generated on today's inputs,
    and the Draft is labelled as such, so no figure is shown as Determined on an undecided item."""
    meta = registry.meta(run_id)
    if meta["open_items"] and generated_now(registry, run_id):
        return
    if meta["open_items"]:
        raise NotReady("decide these items first: " + ", ".join(meta["open_items"]))
    if meta["status"] != "done":
        raise NotReady("the run has not finished")


def build(registry: Registry, run_id: str) -> dict[str, Any]:
    """The gates are the engine's own invariant and oracle checks, run again on this run's files."""
    require_done(registry, run_id)
    run = stage(build_context(registry.data_dir(run_id), registry.config_dir(run_id)))
    registry.update(run_id, built=True)
    gates = [{"name": c.name, "ok": c.ok, "detail": c.detail} for c in run.checks]
    return {"gates": gates, "passed": run.checks_passed, "blocked": run.blocked, "stages": run_log(registry, run_id)}


_CARDS: dict[tuple[str, int, int], list[dict[str, Any]]] = {}


def result_cards(registry: Registry, run_id: str, items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Cards for a finished run's issues.json rows: the same wording as the review step, with no decision buttons.
    Building them re-runs the engine and the ledger replay (about 70 ms), and the page asks for them on every file it
    shows, so they are kept per run until its issues file or the ledger changes."""
    issues = registry.out_dir(run_id) / "issues.json"
    key = (run_id, issues.stat().st_mtime_ns, load_llm_config().ledger_path.stat().st_mtime_ns)
    if key not in _CARDS:
        run = stage(build_context(registry.data_dir(run_id), registry.config_dir(run_id)))
        units = ai_service.review_units(registry, run_id)["units"]
        dispositions = [d.model_dump(mode="json") for d in run.dispositions]
        _CARDS[key] = build_cards(items, units, dispositions, [], journal_memos(run))
    return _CARDS[key]


def run_log(registry: Registry, run_id: str) -> list[dict[str, Any]]:
    """The stages this run really logged, oldest first, without file paths."""
    events = []
    for path in sorted((registry.folder(run_id) / "logs").glob("*.jsonl")):
        for line in path.read_text(encoding="utf-8").splitlines():
            row = json.loads(line)
            events.append({k: v for k, v in row.items() if k not in {"run_id", "data_dir", "folder"}})
    return sorted(events, key=lambda e: str(e["ts"]))

"""Choose outputs before generating, sign off the generated files, and read the calculation behind an output row."""
import re
from typing import Any

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

from app.routes import Reg
from app.services import calculation_service, signoff_service
from app.services import pipeline_service as pipeline
from app.services import results_service as results
from app.services.run_service import OUTPUT_FILES

router = APIRouter(prefix="/api")
TARGET = re.compile(r"^[A-Za-z0-9_.-]{1,60}$")


class Mark(BaseModel):
    file: str
    reviewer: str
    row: str | None = None  # a row mark, bound to the file's hash; none means the whole file


class Plan(BaseModel):
    files: list[str]


@router.get("/runs/{run_id}/output-plan")
def get_plan(run_id: str, reg: Reg) -> dict[str, Any]:
    """The nine output files, known before anything is generated, and the ones chosen so far."""
    meta = reg.meta(run_id)
    if meta["status"] == "new":
        raise HTTPException(409, "scan the files first: nothing has been analysed yet")
    return {"available": [{"name": n, "required": n == results.ALWAYS} for n in [*OUTPUT_FILES, results.ALWAYS]],
            "chosen": meta["outputs"]}


@router.put("/runs/{run_id}/output-plan")
def set_plan(run_id: str, body: Plan, reg: Reg) -> dict[str, Any]:
    allowed = {*OUTPUT_FILES, results.ALWAYS}
    unknown = sorted(set(body.files) - allowed)
    if unknown:
        raise HTTPException(422, "not an output file: " + ", ".join(unknown))
    if reg.meta(run_id)["status"] == "new":
        raise HTTPException(409, "scan the files first: nothing has been analysed yet")
    order = [*OUTPUT_FILES, results.ALWAYS]
    return reg.update(run_id, outputs=sorted({*body.files, results.ALWAYS}, key=order.index))


@router.get("/runs/{run_id}/signoff")
def get_signoff(run_id: str, reg: Reg) -> dict[str, Any]:
    pipeline.require_done(reg, run_id)
    return signoff_service.status(reg, run_id)


@router.post("/runs/{run_id}/signoff")
def mark_reviewed(run_id: str, body: Mark, reg: Reg) -> dict[str, Any]:
    pipeline.require_done(reg, run_id)
    try:
        return signoff_service.mark(reg, run_id, body.file, body.reviewer, body.row)
    except ValueError as error:
        raise HTTPException(422, str(error)) from error


@router.get("/runs/{run_id}/calculation/{target}")
def get_calculation(run_id: str, target: str, reg: Reg) -> dict[str, Any]:
    pipeline.require_done(reg, run_id)
    if not TARGET.match(target):
        raise HTTPException(422, "not a figure key or account code")
    found = calculation_service.calculation(reg, run_id, target)
    if found is None:
        raise HTTPException(404, f"no calculation was recorded for {target}")
    return found

